import{_ as a,c as e,o as d,ag as r}from"./chunks/framework.C86mscM5.js";const _=JSON.parse('{"title":"部署与发布","description":"","frontmatter":{},"headers":[],"relativePath":"devops/deployment/index.md","filePath":"devops/deployment/index.md","lastUpdated":1788689791000}'),l={name:"devops/deployment/index.md"};function o(i,t,n,s,h,c){return d(),e("div",null,t[0]||(t[0]=[r('<h1 id="部署与发布" tabindex="-1">部署与发布 <a class="header-anchor" href="#部署与发布" aria-label="Permalink to &quot;部署与发布&quot;">​</a></h1><p>部署是把制品安装到环境，发布是让用户开始使用新版本。二者分离后，可以先完成技术部署，再通过流量或功能开关逐步发布。</p><h2 id="最小生产流程" tabindex="-1">最小生产流程 <a class="header-anchor" href="#最小生产流程" aria-label="Permalink to &quot;最小生产流程&quot;">​</a></h2><ol><li>选择已验证的不可变制品和配置版本。</li><li>执行部署，等待启动和就绪检查通过。</li><li>执行烟雾测试并观察核心 SLI。</li><li>逐步扩大流量或开启功能。</li><li>达到失败阈值时停止推广并回滚。</li></ol><h2 id="发布策略" tabindex="-1">发布策略 <a class="header-anchor" href="#发布策略" aria-label="Permalink to &quot;发布策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>Recreate</td><td>停旧启新，有中断</td><td>可停机的简单系统</td></tr><tr><td>Rolling</td><td>分批替换实例</td><td>常规无状态服务</td></tr><tr><td>Blue/Green</td><td>两套完整环境切换</td><td>需要快速整体回退</td></tr><tr><td>Canary</td><td>新版本逐步接收流量</td><td>能按指标自动判断风险</td></tr></tbody></table><p>前端静态资源应使用带内容哈希的文件名，先上传新资源再切换 HTML，旧资源保留至少一个回滚周期。不要用 CDN 全量清缓存代替版本化。</p><h2 id="发布验证" tabindex="-1">发布验证 <a class="header-anchor" href="#发布验证" aria-label="Permalink to &quot;发布验证&quot;">​</a></h2><ul><li><strong>健康检查</strong>：进程是否存活、是否可以接收流量。</li><li><strong>烟雾测试</strong>：登录、查询、下单等关键路径是否可用。</li><li><strong>技术指标</strong>：错误率、延迟、饱和度和依赖健康度。</li><li><strong>用户指标</strong>：页面加载、关键交互和业务成功率。</li></ul><h2 id="回滚条件" tabindex="-1">回滚条件 <a class="header-anchor" href="#回滚条件" aria-label="Permalink to &quot;回滚条件&quot;">​</a></h2><p>发布前定义错误率、延迟、业务指标和观察窗口。超过阈值时自动暂停流量扩大；确认是版本问题后重新部署上一已验证制品。数据库迁移必须兼容新旧版本，避免应用回滚后无法读取数据。</p><h2 id="功能开关" tabindex="-1">功能开关 <a class="header-anchor" href="#功能开关" aria-label="Permalink to &quot;功能开关&quot;">​</a></h2><p>功能开关适合将代码部署和业务发布分离，但需要所有者、过期时间、审计和清理机制。它不能替代权限控制。</p>',13)]))}const u=a(l,[["render",o]]);export{_ as __pageData,u as default};
